package app.familyhub.server.platform

import java.util.Properties

/** Build metadata generated by Gradle (`generateBuildInfo` in server/build.gradle.kts). */
data class BuildInfo(
    val version: String,
) {
    companion object {
        private const val RESOURCE = "/familyhub-build.properties"

        fun load(): BuildInfo {
            val properties = Properties()
            BuildInfo::class.java.getResourceAsStream(RESOURCE)?.use(properties::load)
            return BuildInfo(version = properties.getProperty("version") ?: "unknown")
        }
    }
}
